package frc.robot.subsystems.IntakeSubsystem;import org.littletonrobotics.junction.Logger;import org.littletonrobotics.junction.networktables.LoggedNetworkNumber;import com.ctre.phoenix6.configs.TalonFXConfiguration;import com.ctre.phoenix6.controls.DynamicMotionMagicVoltage;import com.ctre.phoenix6.controls.VoltageOut;import com.ctre.phoenix6.hardware.TalonFX;import edu.wpi.first.wpilibj2.command.SubsystemBase;public class IntakeSubsystemCopy extends SubsystemBase {private static IntakeSubsystemCopy INSTANCE;public enum IntakeState {INTAKING,IDLING,STORING,ZEROING}private DynamicMotionMagicVoltage IntakeArmMMRequest =  IntakeConstants.IntakeArmMMRequest;private VoltageOut IntakeWheelMMRequest = IntakeConstants.IntakeWheelMMRequest;private TalonFX mArmFx = IntakeConstants.mArmFx;private TalonFX mIntakeWheelFx = IntakeConstants.mIntakeWheelFx;public IntakeState currentIntakeState = IntakeState.ZEROING;private LoggedNetworkNumber logIntakeRevolutionTargetStore = new LoggedNetworkNumber("Rebuilt/Intake/Tuning/Revolution/StoreTarget", 0);private LoggedNetworkNumber logIntakeRevolutionTargetIntaking = new LoggedNetworkNumber("Rebuilt/Intake/Tuning/Revolution/IntakeTarget", 0);private LoggedNetworkNumber logIntakeRevolutionTargetIdling = new LoggedNetworkNumber("Rebuilt/Intake/Tuning/Revolution/IdlingTarget", 0);private double intakeRevolutionTarget = 0;private IntakeSubsystemCopy() {}
@Override
public void periodic() {applyState();publishLog();updateConstants();}private void applyState() {switch (currentIntakeState) {case ZEROING:zeroing();IntakeWheelMMRequest.Output = 0;case INTAKING:intakeRevolutionTarget = logIntakeRevolutionTargetIntaking.get();IntakeWheelMMRequest.Output = 3;break;case IDLING:intakeRevolutionTarget = logIntakeRevolutionTargetIdling.get();IntakeWheelMMRequest.Output = 0;break;case STORING:intakeRevolutionTarget = logIntakeRevolutionTargetStore.get();IntakeWheelMMRequest.Output = 0;break;}mArmFx.setControl(IntakeArmMMRequest.withPosition(intakeRevolutionTarget));mIntakeWheelFx.setControl(IntakeWheelMMRequest);}private void zeroing() {    mArmFx.setVoltage(-1);if (Math.abs(mArmFx.getVelocity().getValueAsDouble()) < .05 && Math.abs(mArmFx.getMotorVoltage().getValueAsDouble()) > .4) {mArmFx.setVoltage(0);mArmFx.setPosition(0);currentIntakeState = IntakeState.STORING;}}private void publishLog(){Logger.recordOutput("Rebuilt/Intake/currentState", currentIntakeState);Logger.recordOutput("Rebuilt/Intake/Motors/Arm/ArmPosition", mArmFx.getPosition().getValueAsDouble());Logger.recordOutput("Rebuilt/Intake/Motors/Wheal/WhealVelocity", mIntakeWheelFx.getVelocity().getValueAsDouble());}private void updateConstants() {TalonFXConfiguration motorConfig = IntakeConstants.motorConfig; if (motorConfig.MotionMagic.MotionMagicAcceleration != IntakeConstants.logIntakeMMAccel.get() ||motorConfig.MotionMagic.MotionMagicCruiseVelocity != IntakeConstants.logIntakeMMVeloc.get() ||motorConfig.Slot0.kS != IntakeConstants.logIntakeMMKS.get() ||motorConfig.Slot0.kV != IntakeConstants.logIntakeMMKV.get() ||motorConfig.Slot0.kA != IntakeConstants.logIntakeMMKA.get() ||motorConfig.Slot0.kP != IntakeConstants.logIntakeMMKP.get() ||motorConfig.Slot0.kI != IntakeConstants.logIntakeMMKI.get() ||motorConfig.Slot0.kD != IntakeConstants.logIntakeMMKD.get() ||motorConfig.Slot0.kG != IntakeConstants.logIntakeMMKG.get()) {IntakeConstants.configureArmMotor();}}public static IntakeSubsystemCopy getInstance() {if (INSTANCE == null) {INSTANCE = new IntakeSubsystemCopy();} return INSTANCE;}}
